#include <stdlib.h>
int main(int argc,char**argv) {
    int m,n;
    scanf("%d%d",&m,&n);
    int a[500][500],order[500],max[500];
    for(int i=0;i<m;i++) {
        order[i]=i;
        max[i]=0;
        for(int j=0;j<n;j++) {
            a[i][j]=atoi(argv[1+i*n+j]);
            if(a[i][j]>max[i])max[i]=a[i][j];
        }
    }
    for(int i=1;i<m;i++) {
        int j=i;
        while(j>0&&max[order[j]]>max[order[j-1]]) {
            int t=order[j];
            order[j]=order[j-1];
            order[j-1]=t;
            j--;
        }
    }
    for(int i=0;i<m;i++) {
        for(int j=0;j<n;j++)printf("%d ",a[order[i]][j]);
        puts("");
    }
    return 0;
}
